function UIRoleSwitchDialog:__init()
    self.isInitFilter = false
    self.curSelectId = -1
    self.signboardId = 0
    self.state = 0
    self.catSwitchButton = nil
    self.lockTrans = nil
end

function UIRoleSwitchDialog:__delete()
    self.curSelectIdList = nil
    self.signboardId = 0
    self.state = 0
    self.curSelectId = -1
    self.catSwitchButton = nil
    self.lockTrans = nil
end

function UIRoleSwitchDialog:Awake()

    self.catSwitchButton = self.BtnGift.transform.parent:Find("BtnTransformation")
    if self.catSwitchButton then
        local lockTrans = self.catSwitchButton:Find("ImgIcon")
        if lockTrans then
            self.lockTrans = lockTrans
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 3)
        end
        SetButtonAction(self.catSwitchButton, Bind(self, self.OnSwitchCatAction))
    end
    self:InitData()

    self:InitUI()

end

function UIRoleSwitchDialog:OnSwitchCatAction()
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(self.signboardId)
    ---@type CardVo
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
    if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
        GameUtils.Toast(localize('好感度达到_level_级解锁', { _level_ = cardVo.mainCat }))
        return
    end

    ----当前是猫还是人
    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
    if self.state == state then
        return
    end
    self.state = state
    if self.lockTrans then
        CfUtils.SetUISwitchImage(self.lockTrans.gameObject, state)
    end
    if state == 1 then
        state = 2
    else
        state = 1
    end
    if checkNumber(self.signboardId) > 0 then
        ---@type XMainHome
        local homeEnv = UIModule.CurrentScreen.Env
        if homeEnv then
            local cameraState = state == 1 and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.SignboardRoleToCat
            homeEnv:ShowSignboard(cardDojo, cameraState, state)
        end
    end
end

function UIRoleSwitchDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        EasyTouch.instance.allowUIDetection = false
        self:InitNavBar()
    end))
    return coWait
end

function UIRoleSwitchDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
        ---@type CardProgressionUtils
        local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
        ---@type CardProgressionControllerRole
        local env = CardProgressionUtils.GetRoleControllerEnv()
        if env then
            local newState = state
            if newState == 3 then
                newState = 1
            end
            if state == 3 then
                ---@type CardComponent
                local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local cardDojo = cardComponent:GetCardById(self.signboardId)
                local go = env:GetRoleBySkinId(cardDojo.cardSkin)
                if isNull(go) then
                    env:LoadRole(cardDojo.cardSkin, true, { newState == 1 and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.SignboardRoleToCat }, nil, cardDojo)
                else
                    env:FreshCameraState(newState == 1 and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.SignboardRoleToCat)
                end
            else
                env:FreshCameraState(newState == 1 and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.SignboardRoleToCat)
            end
        end
        self:RefreshUI()
    end))
    return coWait
end

function UIRoleSwitchDialog:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        EasyTouch.instance.allowUIDetection = true
        ---@type UINavigatorBar
        local env = CfUtils.GetLuaScr(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
        if not IsNull(env) then
            env:SetCustomBackHandlerAction()
        end
    end))
    return coWait
end

function UIRoleSwitchDialog:OnFinalize()
