function UIRoleSwitchDialog:InitData()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local signboardId = playerComponent:GetSignboardId()
    ---@type CardVo
    local cardVo = playerComponent:GetSignboardCardVo()
    local characterId = cardVo.characterId
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local originIdList = cardComponent:GetAllCardTable()
    local t = {}
    for i, v in pairs(originIdList) do
        ---@type CardSkinVo
        local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(v.cardSkin)
        if cardSkinVo then
            ---@type CardVo
            local cardVo = cardConfMgr:GetCardByRefId(cardSkinVo.roleId)
            if cardVo and cardVo.signboard == 1 then
                table.insert(t, v)
            end
        end
    end
    self.originIdList = t
    self.signboardId = signboardId
    if self.controller.Argument.parameters then
        if checkNumber(self.controller.Argument.parameters.signboardId) > 0 then
            self.signboardId = checkNumber(self.controller.Argument.parameters.signboardId)
            self.curSelectId = self.signboardId
        end
    end
    self.originId = signboardId
    self.characterId = characterId

    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
    self._initState = state
end

---GetFavoriteAbilityLevel
---获取最高好感度等级
---@param cardId number
function UIRoleSwitchDialog:GetFavoriteAbilityLevel(cardId)
    local ids = cardConfMgr:GetFavorableExpRewardIdGroup(cardId)
    local maxLevel = 0
    for i, id in ipairs(ids) do
        ---@type FavorableExpRewardVo
        local vo = cardConfMgr:GetFavorableExpRewardVo(id)
        if vo ~= nil then
            maxLevel = math.max(maxLevel, vo.level)
        end
    end
    return maxLevel
end

function UIRoleSwitchDialog:InitUI()
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComponent:GetCardById((checkNumber(self.curSelectId) > 0 and self.curSelectId) or self.signboardId)
    ---@type CardSkinVo
    local vo = cardConfMgr:GetCardSkinBySkinId(cardDojo.cardSkin)
    self.TxtName.text = vo.name
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(vo.roleId)
    self:FreshNameUI(vo, cardVo, cardDojo.favorabilityLevel)
    ---确定的
    SetButtonAction(self.FontStyleWithIconButton1, Bind(self, self.OnClickBtnConfirmAction))
    --cancel取消的
    SetButtonAction(self.FontStyleWithIconButton2, function()
        --取消的逻辑
        self:OnCustomBackHandlerAction()
    end)
    SetButtonAction(self.BtnGift, function()
        self.controller.Argument.parameters.signboardId = checkNumber(self.signboardId)

        ---@type CardComponent
        local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local dojo = cardComp:GetCardById(self.signboardId)
        CfUtils.DialogOpen(Constants.UITypeIds.CardProgressionIntroduction, {cardId = dojo.cardId, playerCardId = self.signboardId, favorLevel = dojo.favorabilityLevel, viewType = CardProgressionConstants.IntroductionViewType.Favor}, {
            UIArgs(Constants.UITypeIds.UIChangeCharacterBillboard)
        })

    end)
end

function UIRoleSwitchDialog:InitCommonFilterNode()
    ---三个筛选按钮
    local filterMB = GetLuaBehaviour(self.CommonFilterNode.gameObject, UICommonFilterMBPath)
    if not isNull(filterMB) and not isNull(filterMB.Env) then
        ---@type UICommonFilterMB
        local filterNodeEnv = filterMB.Env
        local allCharacterCards = checkTable(self.originIdList)

        filterNodeEnv:SetCallback(allCharacterCards, function(data)
            if data then
                self.cards = data
                self:ResortByLive3D(self.cards)
                self:RefreshGridView()
            end
        end)
        ---@type SuperScrollView.LoopGridView
        filterNodeEnv:RestoreState(Constants.UICacheDataKeys.UICultivateEntryFilterState, function(data)
            if isNull(data) then
                self.cards = CardUtils.SortCardBySortType(allCharacterCards, Constants.SortType.Quality, true)
            else
                self.cards = data
            end
            self:ResortByLive3D(self.cards)
            self:RefreshGridView()
        end)
    end
end

function UIRoleSwitchDialog:InitNavBar()
    UINavigationBarRoot.Instance:SetActive(true)

    ---@type UINavigatorBar
    local env = CfUtils.GetLuaScr(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
