---FreshGridView
---刷新gridview列表数据
function UIRoleSwitchDialog:RefreshGridView(isInitialize)
    --刷新列表
    local len = #self.cards
    local gridView = self.ScrollView
    if not gridView.IsListViewInit then
        gridView:InitGridView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(gridView, len)
    end
end

---OnGetItemByIndex
---签到当前页签的值
---@param listView SuperScrollView.LoopGridView
---@param index number
function UIRoleSwitchDialog:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return
    end
    local position = index + 1
    if position > #self.cards then
        return
    end
    local cell = listView:NewListViewItem(PrefabName)
    ---@type CardDojo
    local cardDojo = self.cards[position]
    if isNull(cardDojo) then
        return nil
    end
    ---@type Engine.Modules.LuaBehaviour
    local headNode = GetLuaBehaviour(cell.gameObject, UISwitchCellNodePath)
    ---@type UISwitchCellNode
    local env = headNode.Env
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        --是否需要cell的init的逻辑
        headNode:Init()
        env = headNode.Env
        env:SetClickAction(Bind(self, self.OnClickCellAction))
    end
    if not KTool.IsNull(headNode) then
        env:FreshUI(cardDojo, position)
        env:SetSelected(self.curSelectId == checkNumber(cardDojo.id), self.originId, checkNumber(cardDojo.id))
    end
    return cell
end

