---FreshNameUI
---@param skinVo CardSkinVo
---@param cardVo CardVo
function UIRoleSwitchDialog:FreshNameUI(skinVo, cardVo, favorabilityLevel)
    self.TxtName.text = skinVo.name
    ---@type RolesVo
    local typeVo = CfUtils.GetCfVo(AutoIds.IdSetting19, "RolesVo", cardVo.characterId)
    --self.TxtEnglishName.text = typeVo.englishName
    self.TxtNumber.text = favorabilityLevel
    local maxLevel = self:GetFavoriteAbilityLevel(cardVo.refId)
    local imageFrame = self.TxtNumber.transform.parent:Find("ImgFrame")
    local fullLevelAnim = self.TxtNumber.transform.parent:Find("UIFX_Level/UIFX_CultivateOverseaFeelingLevelAnim")
    if fullLevelAnim then
        KTool.SetActive(fullLevelAnim.gameObject, checkNumber(favorabilityLevel) >= maxLevel)
    end
    ---达到最高好感度等级
    if imageFrame then
        if checkNumber(favorabilityLevel) >= maxLevel then
            CfUtils.SetUISwitchImage(imageFrame, 2)
        else
            CfUtils.SetUISwitchImage(imageFrame, 1)
        end
    end
    if self.lockTrans then
        ---@type CardComponent
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local cardDojo = cardComponent:GetCardById(self.signboardId)
        local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
        if state == 1 then
            state = 2
        else
            state = 1
        end
        if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 3)
        else
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, state)
        end
    end
end

---RefreshRole
---@param playerCardId number 卡牌皮肤id
---@param isPreview boolean 是否看板娘
function UIRoleSwitchDialog:RefreshRole(playerCardId, isPreview)
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(playerCardId)
    ---@type CardSkinVo
    local vo = cardConfMgr:GetCardSkinBySkinId(cardDojo.cardSkin)
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(vo.roleId)
    self:FreshNameUI(vo, cardVo, cardDojo.favorabilityLevel)

    ----当前是猫还是人
    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
    local cameraState
    if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
        state = 1 ---未解锁的情况下只能切换人
        self.state = 0
        cameraState = isPreview and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.HomeFull
    else
        if state == 1 then
            cameraState = isPreview and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.HomeFull
        elseif state == 2 then
            cameraState = isPreview and CardProgressionConstants.CameraState.SignboardRoleToCat or CardProgressionConstants.CameraState.HomeRoleToCat
        else
            state = 1 ---不是人或猫的情况下只能切换人
            self.state = 0
            cameraState = isPreview and CardProgressionConstants.CameraState.SignboardRoleFull or CardProgressionConstants.CameraState.HomeFull
        end
    end

    ---获取场景
    ---@type XMainHome
    local homeEnv = UIModule.CurrentScreen.Env
    if homeEnv then
        homeEnv:ShowSignboard(cardDojo, cameraState, state)
    end
end

---SwitchUIShowState
---切换UI显示状态
---@param isShowDialogue boolean 是否显示弹窗
function UIRoleSwitchDialog:SwitchUIShowState(isShowDialogue)
    if not isShowDialogue and not self.isInitFilter then
        self.isInitFilter = true
        self:InitCommonFilterNode()
        self:RefreshGridView()
    end
end

