function UIRoleSwitchDialog:OnCustomBackHandlerAction()
    --- 记录进入更换界面前的形态，区分猫和人形态。点取消和返回时，都保留原有形态返回到主界面
    CfUtils.WriteLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, self._initState)

    UIModule.BackDialog()
end

function UIRoleSwitchDialog:OnClickBtnConfirmAction()
    --- 2. 检查选择的卡牌是否改变
    if checkNumber(self.originId) == checkNumber(self.signboardId) then
        UIModule.BackDialog()
        return
    end
    --- 3. 发送请求 或 直接退出
    GameUtils.Request(Interfaces.PlayerSignboard, { playerCardId = self.signboardId }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            GameUtils.Toast(localize("保存成功"))
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComponent.playerDojo.signboardId = checkNumber(self.signboardId)
            local signboardId = checkNumber(playerComponent.playerDojo.signboardId)
            self:RefreshRole(signboardId)
            UIModule.BackDialog()
            --self.originId = signboardId
            --self.signboardId = signboardId
            --self:RefreshUI()
        end
    end)
end

---OnClickCellAction
---@param cardDojo CardDojo
---@param position number
function UIRoleSwitchDialog:OnClickCellAction(cardDojo, position)
    if self.curSelectId == checkNumber(cardDojo.id) then
        return
    end
    self.curSelectId = checkNumber(cardDojo.id)
    local playerCardId = tostring(cardDojo.id)
    self:RefreshGridView()
    self:RefreshTxtSelectedNum()
    if playerCardId ~= self.signboardId then
        self.signboardId = playerCardId
        --- 刷新模型
        self:RefreshRole(playerCardId, true)
        
    end
end

