function UIRoleSwitchDialog:ResortByLive3D(cards)
    table.inPlaceBubbleSort(cards, function(a, b)
        local aValue = 0
        local bValue = 0
        if isSet(a, "cardSkin") then
            local live3DCardVo = IdolLive3D_Utils.GetLive3DCardVoRow(a.cardSkin)
            if live3DCardVo then
                aValue = 1
            end
        end
        if isSet(b, "cardSkin") then
            local live3DCardVo = IdolLive3D_Utils.GetLive3DCardVoRow(b.cardSkin)
            if live3DCardVo then
                bValue = 1
            end
        end
        return aValue > bValue
    end)
end

return UIRoleSwitchDialog